// ============================================================
// Voxora Feedback Report
// Renders a SAMPLE feedback report — NOT generated by real AI.
// In production, this would be based on actual analysis of the
// user's answers, speech patterns, and camera presence.
// ============================================================

const Feedback = {
  render(answers) {
    const data = SAMPLE_FEEDBACK;
    const totalQuestions = MOCK_QUESTIONS.length;
    const answeredCount = answers.filter(a => a && a.answer !== '[Skipped]').length;

    // Animate overall score
    this.animateScore(data.overallScore);

    // Animate category bars
    setTimeout(() => {
      document.querySelectorAll('.breakdown-fill').forEach((bar, i) => {
        const score = data.categories[i] ? data.categories[i].score : 0;
        bar.style.width = score + '%';
      });
    }, 300);

    // Strengths
    const strengthsList = document.getElementById('strengths-list');
    strengthsList.innerHTML = data.strengths.map(s => `<li>${s}</li>`).join('');

    // Weaknesses
    const weaknessesList = document.getElementById('weaknesses-list');
    weaknessesList.innerHTML = data.weaknesses.map(w => `<li>${w}</li>`).join('');

    // Tips
    const tipsList = document.getElementById('tips-list');
    tipsList.innerHTML = data.tips.map(t => `
      <div class="tip-card">
        <div class="tip-card-tip">Tip</div>
        <p><strong>${t.title}.</strong> ${t.text}</p>
      </div>
    `).join('');

    // Per-question breakdown
    const breakdown = document.getElementById('answers-breakdown');
    breakdown.innerHTML = data.perQuestion.map(pq => {
      const q = MOCK_QUESTIONS[pq.qIndex];
      const userAnswer = answers[pq.qIndex];
      const answerText = userAnswer
        ? (userAnswer.answer === '[Skipped]' ? '<em>Skipped</em>' : this.escapeHtml(userAnswer.answer))
        : '<em>No answer provided</em>';

      return `
        <div class="answer-item">
          <div class="answer-item-q">
            <span class="answer-item-q-num">Q${pq.qIndex + 1}.</span>
            <span>${this.escapeHtml(q.text)}</span>
          </div>
          <div class="answer-item-a">${answerText}</div>
          <div class="answer-item-score">
            <span>Score: <strong>${pq.score}</strong>/100</span>
            <div class="answer-item-score-bar">
              <div class="answer-item-score-fill" style="width:${pq.score}%"></div>
            </div>
          </div>
          <p style="font-size:13px;color:var(--text-dim);margin-top:8px;">${pq.comment}</p>
        </div>
      `;
    }).join('');
  },

  animateScore(target) {
    const scoreEl = document.getElementById('score-num');
    const ring = document.getElementById('score-ring-progress');
    const circumference = 2 * Math.PI * 70; // ~440
    const offset = circumference - (circumference * target / 100);

    let current = 0;
    const duration = 1200;
    const steps = 60;
    const increment = target / steps;
    const interval = duration / steps;

    const timer = setInterval(() => {
      current += increment;
      if (current >= target) {
        current = target;
        clearInterval(timer);
      }
      scoreEl.textContent = Math.round(current);
    }, interval);

    // Animate ring
    setTimeout(() => {
      ring.style.transition = 'stroke-dashoffset 1.2s ease';
      ring.style.strokeDashoffset = offset;
    }, 100);
  },

  escapeHtml(str) {
    const div = document.createElement('div');
    div.textContent = str;
    return div.innerHTML;
  }
};
